// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 val, address actor) public {
        // Admissible domain: any value where _val + 1 does not overflow uint256.
        vm.assume(val < type(uint256).max);
        vm.assume(actor != address(0));

        vm.prank(actor);
        c.SetMinSum(val);

        // General rule: SetMinSum stores exactly the supplied value in MinSum.
        assertTrue(c.MinSum() == val);
    }
}
